(()=>{'use strict';
if(window.DEMO_PAGE?.id!=='BL-02-03')return;
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],key='blacklake-demo-v29-calculations';
let popup=null,menu=null,activeName='',focusBack=null,draftMinus=[];const labels={};let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch{}
function close(){popup?.remove();popup=null;focusBack?.focus();}
function sync(input){const span=input.closest('.kodo-new-checkbox,.kodo-new-radio');span?.classList.toggle(input.type==='radio'?'kodo-new-radio-checked':'kodo-new-checkbox-checked',input.checked);input.closest('label')?.classList.toggle(input.type==='radio'?'kodo-new-radio-wrapper-checked':'kodo-new-checkbox-wrapper-checked',input.checked);}
function preview(){const dialog=$('[role=dialog]',popup),inputs=$$('input',dialog),chosen=inputs.filter(e=>e.checked),add=chosen.find(e=>e.type==='radio'),minus=draftMinus.map(value=>labels[value]);let text;
if(activeName==='净需求数')text='净需求数 = 父项'+labels[add?.value]+' * 当前层级的单位用量';else{text=activeName+' = '+(labels[add?.value]||'库存数量');if(minus.length)text+=' - '+(minus.length>1?'('+minus.join(' + ')+')':minus[0]);}
const target=$('.displayText__uDQib',dialog);if(target){let node=[...target.childNodes].find(e=>e.nodeType===Node.TEXT_NODE);if(!node){node=document.createTextNode('');target.prepend(node);}node.textContent=text;}
inputs.forEach(sync);
}
function open(name){menu?.remove();menu=null;close();activeName=name;const html=window.REVIEWED_V29_CALC_ASSETS?.[name];if(!html)return;popup=document.createElement('div');popup.dataset.v29Calc='';popup.innerHTML='<div class="kodo-new-modal-mask"></div><div class="kodo-new-modal-wrap">'+html+'</div>';document.body.append(popup);const dialog=$('[role=dialog]',popup);dialog.style.transformOrigin='';dialog.style.top='';dialog.style.margin='';dialog.setAttribute('aria-label',name);$$('input',dialog).forEach(input=>{labels[input.value]=input.closest('label')?.textContent.trim()||input.value;if(!input.disabled&&Array.isArray(saved[name]))input.checked=saved[name].includes(input.value);});const checked=$$('input[type=checkbox]:checked',dialog).filter(e=>name!=='可用库存'||e.value!=='stockBalance').map(e=>e.value);draftMinus=Array.isArray(saved[name])?saved[name].filter(v=>checked.includes(v)):checked;preview();$('[aria-label=Close]',dialog)?.focus();}
window.addEventListener('click',e=>{const button=e.target.closest('button');if(popup&&popup.contains(e.target)){if(button){const text=button.textContent.replace(/\s/g,'');if(button.getAttribute('aria-label')==='Close'||text==='取消'){e.preventDefault();e.stopImmediatePropagation();close();return;}if(text==='确定'){e.preventDefault();e.stopImmediatePropagation();saved[activeName]=[...$$('input[type=radio]:checked',popup).map(i=>i.value),...draftMinus];try{localStorage.setItem(key,JSON.stringify(saved));}catch{window.DEMO_CONTEXT.toast('本地存储不可用，配置尚未保存');return;}close();window.DEMO_CONTEXT.toast('配置已保存在本地，未重算历史数量');return;}}if(e.target.closest('label,input')){e.stopImmediatePropagation();return;}}
if(e.target.closest('[data-v29-calc-menu]')){const item=e.target.closest('[data-calc-name]');if(item){e.preventDefault();e.stopImmediatePropagation();open(item.dataset.calcName);}return;}
if(button?.textContent.trim()==='计算配置'){e.preventDefault();e.stopImmediatePropagation();focusBack=button;if(menu){menu.remove();menu=null;return;}menu=document.createElement('div');menu.dataset.v29CalcMenu='';menu.setAttribute('role','menu');menu.className='v29-calc-menu';for(const name of ['净需求数','计划缺料数','库存缺料数','可用库存','齐套缺料数']){const item=document.createElement('button');item.setAttribute('role','menuitem');item.dataset.calcName=name;item.textContent=name;menu.append(item);}const rect=button.getBoundingClientRect();menu.style.left=Math.min(rect.left,innerWidth-180)+'px';menu.style.top=rect.bottom+4+'px';document.body.append(menu);return;}if(menu){menu.remove();menu=null;}
},true);
window.addEventListener('change',e=>{if(popup?.contains(e.target)&&e.target.matches('input')){e.stopImmediatePropagation();if(e.target.type==='checkbox'){draftMinus=draftMinus.filter(v=>v!==e.target.value);if(e.target.checked)draftMinus.push(e.target.value);}preview();}},true);
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&(popup||menu)){e.preventDefault();e.stopImmediatePropagation();close();menu?.remove();menu=null;}},true);
})();
